"""Автономный двуязычный просмотр адресных свидетельств без сетевых ресурсов."""
import json


def build_primary_html(data):
    encoded = json.dumps(data, ensure_ascii=False).replace("<", "\\u003c").replace("&", "\\u0026")
    return TEMPLATE.replace("__DATA__", encoded)


def build_primary_markdown(data):
    a, v = data["annotation"], data["validation"]
    lines = ["# Первичные источники: квалификация и ограничения", "",
             "Научный критерий успеха ещё не достигнут. В этой итерации новых прогнозов нет: подготовлены первичные данные и проверки их происхождения.", "",
             f"Сохранены {v['verified_sources']} полных JATS-текста, 10 таблиц, {len(a['measurements'])} измерений и {v['verified_fragments']} точных фрагментов в Unicode code points. В числовом карантине: {v['quarantined_measurements']}. Это нерешённые диагностические несогласованности, не доказательство ошибочности статьи. Разметка выполнена Codex и требует экспертной проверки.", "",
             "## Решение по источникам", ""]
    for key, source in a["sources"].items():
        record = next(r for r in data["audit"]["additional_sources"] if r["entry"]["id"] == key)
        lines += [f"- **{source['pmcid']}**, DOI `{record['metadata']['doi']}`: {source['summary']['ru']}"]
    lines += ["", "Три новые публикации не означают три новых независимых подтверждения. GÅS — новый кандидат; EAS повторяет уже известную когорту; PACOS служит контролем границ клинического контекста. Ни один не добавлен автоматически в прежний оператор.", "",
              "## Диагностические ограничения", ""]
    lines += ["- " + issue["description"]["ru"] for issue in a["diagnostics"]]
    lines += ["", "## Будущий контроль", "", a["control_selection"]["note"]["ru"], "",
              "Предварительные кандидаты с нейтральными заголовками: Otassha 2024 — `10.1371/journal.pone.0297433`; Longitudinal Ageing Study in China 2025 — `10.1136/gpsych-2024-101736`. Это только метаданные, не утверждённые контрольные статьи. Их аннотации и полные тексты в этой итерации не читались. Проверка прежнего знакомства не завершена. Нельзя объявлять контроль слепым или успешно предсказанным.", "",
              "## Полные тексты, которые ещё нужны", "",
              "В выбранном маршруте Open Access JATS не получены семь исходных первичных статей. Это не заявление об их недоступности вообще. Приоритет: Roberts, Manly, Katz — проверить исходные ставки, контексты и определения в известных строках обзора.", ""]
    for r in data["audit"]["sources"]:
        lines += [f"- {r['entry']['id']}: `{r['metadata']['doi']}` — {r['status']}."]
    lines += ["", "## Исправление источника и воспроизводимость", "",
              "В первой ревизии Markdown GÅS пропустил три таблицы, вынесенные из body в floats-group. Ревизия 2 восстановила их из того же проверенного оригинального XML, без сети и модельных вызовов. Первая ревизия сохранена, её Markdown не используется для этой квалификации. Исходный XML первой ревизии содержит все таблицы.", "",
              "Ревизия 2 читает только явно зарегистрированные оригинальные источники. Квитанция HTTP второй ревизии пуста. Схемы и карты в UI, GOLD и прежние эксперименты не изменены. AI-клиенты не создаются. Сервисы не менялись, перезапуск не нужен.", "",
              "Числовая согласованность и успешные тесты не являются научной экспертизой. Код и входы связаны хешами в manifest.json. Проверки Python выполняются через Poetry, двуязычного HTML — через Bun/jsdom; это DOM-проверка, не визуальная проверка браузера.", "",
              "## Следующий опыт", "",
              "1. Получить недостающие первичные источники; не заменять их обзорными числами или аннотациями.",
              "2. Проверить совместимость определения исхода, группы риска и возрастных интервалов. Для отсутствующих ДИ сохранить явный null; режим анализа точечных ставок должен быть отдельным и не выдавать статистическую значимость.",
              "3. Зафиксировать состав независимых когорт и переносимый оператор на обучающих данных. Сначала повторить прежнюю диагностику, не подбирать правило под будущий исход.",
              "4. Завершить аудит прежнего знакомства с контрольным кандидатом. Зафиксировать прогноз и критерии оценки до доступа к его результатам.",
              "5. После фиксации открыть полный контрольный текст и сравнить прогноз с частотной базой, отдельно учитывая отказы и несопоставимый контекст.", ""]
    return "\n".join(lines)


TEMPLATE = r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Первичные источники / Primary sources</title>
<style>
:root{color-scheme:light;--ink:#152537;--muted:#465b70;--line:#ccd7e0;--accent:#145d91}*{box-sizing:border-box}body{margin:0;background:#edf2f6;color:var(--ink);font:16px/1.55 system-ui,sans-serif}main{max-width:1250px;margin:auto;padding:24px}header{display:flex;align-items:center;justify-content:space-between;gap:20px}h1{font-size:clamp(24px,4vw,36px);line-height:1.15}h2{font-size:22px}p{max-width:100ch}button,select{font:inherit;padding:9px 14px;border-radius:7px;border:1px solid #7d9db8;background:white;color:var(--ink);cursor:pointer}button:hover{background:#e5f1fa}button.active{background:var(--accent);color:white;border-color:var(--accent)}button:focus-visible,select:focus-visible{outline:3px solid #e59521;outline-offset:2px}.notice{background:#fff5d8;border-left:5px solid #ba8220;padding:16px;border-radius:8px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.stat,.card,section.panel{background:white;border:1px solid var(--line);padding:16px;border-radius:10px}.stat strong{display:block;font-size:28px}.muted{color:var(--muted)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.card h3{margin-top:0}.card button{margin-top:8px}.table-wrap{overflow:auto}table{border-collapse:collapse;background:white;width:100%}th,td{text-align:left;vertical-align:top;padding:10px;border-bottom:1px solid var(--line)}th{background:#dce8f1}code{overflow-wrap:anywhere}.bad{color:#9d2636;font-weight:650}.good{color:#256547}.tag{font-size:13px;display:inline-block;background:#eaf0f6;border-radius:5px;padding:3px 6px}details{margin:14px 0;background:white;border:1px solid var(--line);border-radius:8px;padding:12px}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.65 ui-monospace,monospace}.source-view{max-height:500px;overflow:auto;background:#f6f8fa;padding:16px;border:1px solid var(--line);white-space:pre-wrap;overflow-wrap:anywhere}mark{background:#ffdc80;color:#172435}#detail{position:relative;margin:18px 0}.proof-buttons{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}.diagnostic{border-left:3px solid #d89429;padding:10px 15px;margin:12px 0;background:#fff9e9}.toolbar{display:flex;align-items:center;gap:10px;margin:14px 0;flex-wrap:wrap}.small{font-size:14px}@media(max-width:780px){header{align-items:flex-start}.stats{grid-template-columns:repeat(2,1fr)}.cards{grid-template-columns:1fr}main{padding:14px}}
</style></head><body><main>
<header><h1 data-i="title"></h1><nav aria-label="Language"><button id="ru" class="active">Русский</button> <button id="en">English</button></nav></header>
<p class="notice" data-i="notice"></p><div class="stats" id="stats"></div>
<h2 data-i="sources"></h2><div id="cards" class="cards"></div>
<h2 data-i="measurements"></h2><p class="muted" data-i="numbersNote"></p><div class="toolbar"><label for="source-filter" data-i="filter"></label><select id="source-filter"></select></div>
<div class="table-wrap"><table><thead><tr id="headings"></tr></thead><tbody id="rows"></tbody></table></div>
<section id="detail" class="panel" hidden><h2 data-i="evidence"></h2><p id="detail-meta" class="small muted"></p><pre id="semantic"></pre><div id="proof-buttons" class="proof-buttons"></div><h3 data-i="fragment"></h3><pre id="fragment"></pre><details><summary data-i="fullSource"></summary><div id="source" class="source-view"></div></details></section>
<h2 data-i="diagnostics"></h2><div id="diagnostics"></div>
<details open><summary data-i="control"></summary><p id="control-note"></p><p data-i="controlWarning"></p><ul id="control-list"></ul></details>
<details open><summary data-i="missing"></summary><p data-i="missingNote"></p><ul id="missing-list"></ul></details>
<details><summary data-i="reproducibility"></summary><p data-i="reproNote"></p><pre id="validation"></pre></details>
<p class="muted small" data-i="next"></p>
</main><script type="application/json" id="data">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent);let lang='ru';
const L={ru:{title:'Первичные источники: что можно переносить',notice:'Научный критерий успеха ещё не достигнут. Здесь аудит обучающих источников: новых прогнозов — 0. Разметка Codex требует экспертной проверки.',sources:'Три прочитанные статьи',measurements:'18 измерений с контекстом',numbersNote:'Ставки на 100 и 1000 человеко-лет нормализуются явно. Отсутствующие доверительные интервалы не придуманы. Числовая согласованность не доказывает научную корректность.',filter:'Статья',all:'Все',evidence:'Семантика и происхождение',fragment:'Точный исходный фрагмент (английский)',fullSource:'Полный сохранённый источник и выделенный фрагмент',diagnostics:'Ограничения и несогласованности',control:'Будущий контроль: только метаданные',controlWarning:'Контроль ещё не выбран. Полные тексты и аннотации этих кандидатов в этой итерации не читались; прежнее знакомство не проверено. Некоторые заголовки уже раскрывают результат и не могут считаться слепыми.',missing:'Недостающие первичные тексты — DOI',missingNote:'Эти семь статей не получены выбранным маршрутом Open Access JATS. Это не означает недоступность вообще. Приоритет: Roberts 2012, Manly 2008, Katz 2012.',reproducibility:'Воспроизводимость и проверка',reproNote:'Новая ревизия восстановила три вынесенные таблицы GÅS из сохранённого XML. Повторных сетевых или модельных вызовов нет. Все старые файлы и карты сохранены. Сервисные модули не менялись. HTML использует только встроенные данные; проверки DOM через Bun не заменяют визуальную проверку.',next:'Следующий шаг: первичные тексты → совместимость контекста и независимые когорты → фиксация оператора и прогноза → открытие будущего контроля. Подбор по уже прочитанным исходам остаётся разработкой.',counts:['Полных текстов','Таблиц','Измерений','Новых прогнозов'],heads:['Статья / исход','Контекст','Опубликовано','На 1000 чел.-лет','Проверка','Источник'],inspect:'Посмотреть',consistent:'Числово согласовано',quarantine:'Карантин',noCI:'ДИ не приведён',ci:'ДИ',female:'женщины',male:'мужчины',allSex:'все',age:'возраст',notReported:'не приведён',decision:'Передача оператору пока не разрешена'},en:{title:'Primary sources: what may be transferred',notice:'The scientific success criterion has not been reached. This is a training-source audit: 0 new predictions. Codex annotation requires expert review.',sources:'Three inspected articles',measurements:'18 contextualized measurements',numbersNote:'Rates per 100 and 1000 person-years are explicitly normalized. Missing confidence intervals are not invented. Numerical consistency does not establish scientific validity.',filter:'Article',all:'All',evidence:'Semantics and provenance',fragment:'Exact original fragment (English)',fullSource:'Full saved source and highlighted fragment',diagnostics:'Constraints and inconsistencies',control:'Future control: metadata only',controlWarning:'No control has been selected. No candidate abstracts or full texts were read in this iteration; prior exposure has not been audited. Some inspected titles reveal results and cannot count as blind controls.',missing:'Missing primary full texts — DOIs',missingNote:'These seven papers were not acquired through the selected Open Access JATS route. This does not establish general unavailability. Priority: Roberts 2012, Manly 2008, Katz 2012.',reproducibility:'Reproducibility and verification',reproNote:'The new revision restored three detached GÅS tables from saved XML without additional network or model calls. Previous files and maps are preserved. Service modules are unchanged. This HTML uses embedded data only; Bun DOM checks do not constitute a visual browser review.',next:'Next: primary texts → context compatibility and independent cohorts → freeze the operator and predictions → open a future control. Tuning on already-inspected outcomes remains development.',counts:['Full texts','Tables','Measurements','New predictions'],heads:['Article / outcome','Context','Published','Per 1000 person-years','Audit','Source'],inspect:'Inspect',consistent:'Numerically consistent',quarantine:'Quarantined',noCI:'CI not reported',ci:'CI',female:'women',male:'men',allSex:'all',age:'age',notReported:'not reported',decision:'Transfer into the operator is not yet approved'}};
function el(tag,text,className){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(className)n.className=className;return n}
function evidenceButton(key){const b=el('button',key);b.dataset.proof=key;b.onclick=()=>showFragment(key);return b}
function showFragment(key){const p=data.annotation.evidence[key],t=data.source_texts[p.source_id],parts=Array.from(t);document.getElementById('fragment').textContent=p.text;document.getElementById('fragment').dataset.proof=key;const box=document.getElementById('source');box.replaceChildren(document.createTextNode(parts.slice(0,p.start).join('')),el('mark',parts.slice(p.start,p.end).join('')),document.createTextNode(parts.slice(p.end).join('')))}
function inspect(value,keys){document.getElementById('detail').hidden=false;document.getElementById('semantic').textContent=JSON.stringify(value,null,2);document.getElementById('detail-meta').textContent=keys.join(' · ');document.getElementById('proof-buttons').replaceChildren(...keys.map(evidenceButton));showFragment(keys[0])}
function renderRows(){const rows=document.getElementById('rows');rows.replaceChildren();const filter=document.getElementById('source-filter').value;
 for(const o of data.annotation.measurements){if(filter!=='all'&&o.source_id!==filter)continue;const v=data.validation.measurements.find(x=>x.id===o.id),r=el('tr');r.dataset.measurement=o.id;
 const age=o.context.age_band?o.context.age_band[0]+'–'+(o.context.age_band[1]??'∞'):L[lang].notReported;const sex=L[lang][o.context.sex==='all'?'allSex':o.context.sex];
 const ci=o.confidence_interval?' / '+L[lang].ci+' '+o.confidence_interval.join('–'):' / '+L[lang].noCI;
 const cells=[data.annotation.sources[o.source_id].pmcid+' / '+o.context.event,sex+', '+L[lang].age+' '+age+'; '+o.context.baseline_riskset,o.value+' '+o.unit+ci,v.value_per_1000_person_years??'—',v.status==='quarantined'?L[lang].quarantine:L[lang].consistent];
 cells.forEach((text,i)=>r.append(el('td',text,i===4?(v.issues.length?'bad':'good'):'')));const td=el('td'),b=el('button',L[lang].inspect);b.onclick=()=>inspect({observation:o,audit:v},o.evidence_ids);td.append(b);r.append(td);rows.append(r)} }
function render(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(n=>n.textContent=L[lang][n.dataset.i]);for(const l of ['ru','en'])document.getElementById(l).classList.toggle('active',l===lang);
 document.getElementById('stats').replaceChildren(...[3,10,18,0].map((x,i)=>{const n=el('div',undefined,'stat');n.append(el('strong',String(x)),el('span',L[lang].counts[i]));return n}));
 document.getElementById('cards').replaceChildren(...Object.entries(data.annotation.sources).map(([id,s])=>{const c=el('article',undefined,'card'),m=data.audit.additional_sources.find(x=>x.entry.id===id).metadata;c.append(el('h3',s.pmcid),el('p',m.title,'small'),el('code',m.doi),el('p',s.summary[lang]),el('span',L[lang].decision,'tag'));const b=el('button',L[lang].inspect);b.dataset.source=id;b.onclick=()=>inspect(s,s.evidence_ids);c.append(b);return c}));
 const select=document.getElementById('source-filter'),selected=select.value||'all';select.replaceChildren();for(const [id,name] of [['all',L[lang].all],...Object.entries(data.annotation.sources).map(([id,s])=>[id,s.pmcid])]){const option=el('option',name);option.value=id;select.append(option)}select.value=selected;
 document.getElementById('headings').replaceChildren(...L[lang].heads.map(t=>el('th',t)));renderRows();
 document.getElementById('diagnostics').replaceChildren(...data.annotation.diagnostics.map(d=>{const n=el('div',undefined,'diagnostic');n.append(el('p',d.description[lang]));const b=el('button',L[lang].inspect);b.dataset.diagnostic=d.id;b.onclick=()=>inspect(d,d.evidence_ids);n.append(b);return n}));
 document.getElementById('control-note').textContent=data.annotation.control_selection.note[lang];document.getElementById('control-list').replaceChildren(...data.controls.candidates.map(c=>el('li',c.published_on+' · '+c.doi+' · '+c.title)));
 document.getElementById('missing-list').replaceChildren(...data.audit.sources.map(r=>el('li',r.entry.id+' · '+r.metadata.doi+' · '+r.status)));
 document.getElementById('validation').textContent=JSON.stringify(data.validation,null,2);
}
document.getElementById('ru').onclick=()=>{lang='ru';render()};document.getElementById('en').onclick=()=>{lang='en';render()};document.getElementById('source-filter').onchange=renderRows;render();
</script></body></html>'''
